#!/usr/bin/env bash\nset -e\n\n# Build the Docker image\ndocker build -t test-emoji-clock . > /dev/null\n\n# Run container with fixed time 15:00 (3 PM)\noutput=$(docker run --rm -e FIXED_TIME=2023-01-01T15:00:00 test-emoji-clock)\n\n# Expected emoji for 3 o'clock\nexpected="🕒"\n\nif [ "$output" = "$expected" ]; then\n  echo "PASS"\n  exit 0\nelse\n  echo "FAIL: expected $expected but got $output"\n  exit 1\nfi
